<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ElMessage } from '../lib/notifications'
import { useAuthStore } from '../stores/auth'
import { api, type Data } from '../api/client'
import { confirmAction, dateText } from '../lib/ui'
import Icon from './Icon.vue'
import BackgroundCarousel from './BackgroundCarousel.vue'
import ThemePicker from './ThemePicker.vue'
const auth = useAuthStore(); const route = useRoute(); const router = useRouter()
const mobile = ref(false); const notifications = ref(false); const search = ref(''); const pending = ref<Data[]>([]); const notificationError = ref(''); const loadingNotifications = ref(false)
const nav = [{ path: '/chat', label: 'AI 学习助手', icon: 'spark' }, { path: '/dashboard', label: '学习总览', icon: 'home' }, { path: '/learning', label: '我的学习', icon: 'book' }, { path: '/plans', label: '学习计划', icon: 'calendar' }, { path: '/documents', label: '资料管理', icon: 'file' }, { path: '/knowledge', label: '多专业知识库', icon: 'layers' }, { path: '/questions', label: '练习题库', icon: 'question' }, { path: '/analytics', label: '数据与报告', icon: 'chart' }]
const title = computed(() => route.meta.title)
async function refreshNotifications() { loadingNotifications.value = true; notificationError.value = ''; try { const data = await api.get('/dashboard/today'); pending.value = data.tasks || [] } catch (e) { notificationError.value = (e as Error).message } finally { loadingNotifications.value = false } }
async function toggleNotifications() { notifications.value = !notifications.value; if (notifications.value) await refreshNotifications() }
function doSearch() { if (search.value.trim()) { router.push({ path: '/search', query: { q: search.value.trim() } }); search.value = ''; notifications.value = false } }
async function logout() {
  if (!await confirmAction('退出后需要重新登录，当前账户的数据会保留。', '退出登录')) return
  try { await auth.logout() } catch { ElMessage.warning('本地会话已清除；服务端注销请求未完成。') }
  await router.replace('/login')
}
watch(() => route.fullPath, () => { mobile.value = false; notifications.value = false })
onMounted(refreshNotifications)
</script>
<template><div class="app-shell"><BackgroundCarousel/><button v-if="mobile" class="sidebar-scrim" aria-label="关闭导航" @click="mobile = false"></button><aside id="workspace-navigation" class="sidebar" :class="{ open: mobile }" @keydown.esc="mobile = false"><button class="icon-button sidebar-close" aria-label="收起主导航" @click="mobile = false"><Icon name="close" /></button><RouterLink class="brand" to="/dashboard"><div class="brand-mark"><Icon name="spark" :size="24" /></div><div><strong>StudyMind</strong><small>智学 · 2.0</small></div></RouterLink><span class="nav-caption">学习工作台</span><nav aria-label="主导航"><RouterLink v-for="item in nav" :key="item.path" :to="item.path"><Icon :name="item.icon" /><span>{{ item.label }}</span></RouterLink></nav><div class="sidebar-footer"><div class="side-note"><Icon name="spark" :size="18" /><span>本地优先 · 专注学习</span></div><RouterLink to="/settings" class="settings-link"><Icon name="settings" /> 空间设置</RouterLink><div class="user-card"><RouterLink to="/settings" class="avatar">{{ auth.initials }}</RouterLink><div><strong>{{ auth.user?.display_name || '学习者' }}</strong><small :title="auth.user?.email">{{ auth.user?.email }}</small></div><button class="icon-button" title="退出登录" aria-label="退出登录" @click="logout"><Icon name="logout" :size="17" /></button></div></div></aside><div class="main-shell"><header class="topbar"><div class="breadcrumb"><button class="icon-button mobile-menu" :aria-label="mobile ? '关闭导航' : '展开导航'" :aria-expanded="mobile" aria-controls="workspace-navigation" @click="mobile = !mobile"><Icon name="menu" /></button><span>我的空间</span><span class="slash">/</span><strong>{{ title }}</strong></div><div class="topbar-actions"><ThemePicker compact /><form class="top-search" @submit.prevent="doSearch"><Icon name="search" :size="17" /><input v-model="search" maxlength="100" aria-label="搜索任务、文档、笔记" placeholder="搜索任务、文档、笔记…" /><kbd>↵</kbd></form><RouterLink class="icon-button mobile-search" to="/search" aria-label="打开全局搜索"><Icon name="search" /></RouterLink><div class="notification-wrap"><button class="icon-button notification-button" aria-label="展开待办通知" :aria-expanded="notifications" @click="toggleNotifications"><Icon name="bell" /><span v-if="pending.length" class="notification-dot"></span></button><section v-if="notifications" class="notification-popover"><div class="panel-head"><h3>待办提醒</h3><button class="text-button" @click="refreshNotifications" :disabled="loadingNotifications">刷新</button></div><p v-if="notificationError" class="error-banner">{{ notificationError }}</p><p v-else-if="loadingNotifications" class="muted pad">正在读取待办…</p><template v-else><RouterLink v-for="task in pending" :key="task.id" :to="{ path: '/learning', query: { id: task.id } }" class="notification-item"><span class="small-dot"></span><div><strong>{{ task.title }}</strong><small>{{ task.due_date ? `截止 ${dateText(task.due_date)}` : '没有截止日期' }}</small></div><Icon name="arrow" :size="16" /></RouterLink><p v-if="!pending.length" class="muted pad">没有到期或待安排的任务，继续保持。</p><RouterLink class="notification-all" to="/learning">查看全部学习任务 →</RouterLink></template></section></div><RouterLink to="/settings" class="avatar" title="账户设置">{{ auth.initials }}</RouterLink></div></header><main id="main-content" class="content"><slot /></main><footer class="app-footer">StudyMind <span>让学习留下真实的轨迹</span></footer></div></div></template>
